#!/bin/sh

# Display the live Hyprland bindings: the hyprbar overlay, else Fuzzel.
#
# Querying hyprctl keeps this working when the configuration provider changes
# from hyprland.conf to Lua and also includes bindings generated by loops.

set -eu

# Prefer the visual overlay (quickshell config "keybinds", KeybindOverlay.qml).
# It runs as its own instance, started here on first use. A successful IPC
# call prints nothing; any message means the overlay is unavailable, so fall
# through to the Fuzzel list. --fuzzel forces it.
overlay() {
  output=$(qs -c keybinds ipc call keybinds "$1" 2>&1) && [ -z "$output" ]
}

if [ "${1:-}" != "--fuzzel" ] && command -v qs >/dev/null 2>&1; then
  overlay toggle && exit 0
  if ! qs -c keybinds ipc call keybinds state >/dev/null 2>&1; then
    qs -c keybinds -d >/dev/null 2>&1 || true
    tries=0
    while [ "$tries" -lt 30 ]; do
      overlay open && exit 0
      tries=$((tries + 1))
      sleep 0.1
    done
  fi
fi

hyprctl binds -j | jq -r '
  def hasbit($n): ((.modmask / $n) | floor % 2) == 1;
  def modifiers:
    [if hasbit(64) then "SUPER" else empty end,
     if hasbit(8) then "ALT" else empty end,
     if hasbit(4) then "CTRL" else empty end,
     if hasbit(1) then "SHIFT" else empty end] | join("+");
  def combo:
    (modifiers as $mods | if $mods == "" then .key else $mods + "+" + .key end);

  .[] |
  (if .submap == "" then combo else "[" + .submap + "] " + combo end)
  + "\t"
  + (if .description == "" then (.dispatcher + " " + .arg) else .description end)
' | awk -F '\t' '{ printf "%-28s %s\n", $1, $2 }' | \
  fuzzel --dmenu --only-match --prompt "Hyprland keybindings> " >/dev/null || true
